/*
 * Authenticate the caller and build the message.
 *
 * This workflow can send a real SMS to any number it is handed, so the key
 * check is the only thing standing between the portal's OTP channel and an
 * open SMS relay. It runs before anything else and fails closed.
 */
const crypto = require('crypto');
const KEY = '__OTP_API_KEY__';

const item = $input.first().json;
const hdr = item.headers || {};
const b = item.body || {};

// Compare digests rather than strings: timingSafeEqual throws on a length
// mismatch, and that throw would itself leak how long the secret is.
const given = crypto.createHash('sha256').update(String(hdr['x-api-key'] || '')).digest();
const want = crypto.createHash('sha256').update(KEY).digest();
if (!crypto.timingSafeEqual(given, want)) {
  return [{ json: { ok: false, error: 'Not authorised.' } }];
}

// Indian mobile, in E.164. Anything else is refused rather than dialled.
const e164 = String(b.e164 || '').trim();
if (!/^\+91[6-9][0-9]{9}$/.test(e164)) {
  return [{ json: { ok: false, error: 'A valid +91 mobile number is required.' } }];
}

// Six digits and nothing else. The text below is sent verbatim, so anything
// that is not a code has no business reaching it.
const code = String(b.code || '');
if (!/^[0-9]{6}$/.test(code)) {
  return [{ json: { ok: false, error: 'A six-digit code is required.' } }];
}

const minutes = Math.max(1, Math.round(Number(b.ttlSeconds || 300) / 60));
const sms = `${code} is your MHA Samadhan verification code. It expires in ${minutes} minute${minutes === 1 ? '' : 's'}. Do not share it with anyone.`;

return [{ json: { ok: true, phone_e164: e164, sms, purpose: String(b.purpose || 'login') } }];
